import base64, os, sys, glob, shutil
script_dir = os.path.dirname(os.path.abspath(__file__))
found = glob.glob(os.path.join(script_dir, "**", "super_extractor.py"), recursive=True)
target = [f for f in found if "patch" not in f]
if not target: print("ERROR: not found"); sys.exit(1)
base = os.path.dirname(target[0])
with open(os.path.join(base, "super_extractor.py"), "wb") as f: f.write(base64.b64decode(""))
print("Wrote super_extractor.py")
with open(os.path.join(base, "room_normalizer.py"), "wb") as f: f.write(base64.b64decode(""))
print("Wrote room_normalizer.py")
with open(os.path.join(base, "metadata_extractor.py"), "wb") as f: f.write(base64.b64decode(""))
print("Wrote metadata_extractor.py")
for root, dirs, _ in os.walk(os.path.dirname(base)):
    for d in dirs:
        if d == "__pycache__": shutil.rmtree(os.path.join(root, d))
print("Done!")